-- Populate team history from translations
UPDATE team SET history_en = 'AEK Athens was established in 1924 by Greek refugees from Constantinople in the wake of the Greco-Turkish War. Operating out of Nea Filadelfeia, Athens, the club symbolizes the athletic and cultural heritage of the Greek diaspora.', history_el = 'Η ΑΕΚ ιδρύθηκε το 1924 από Έλληνες πρόσφυγες της Κωνσταντινούπολης. Με έδρα τη Νέα Φιλαδέλφεια της Αθήνας, ο σύλλογος συμβολίζει την αθλητική και πολιτιστική κληρονομιά του Ελληνισμού της Μικράς Ασίας.' WHERE id = 'aek';
UPDATE team SET history_en = 'Founded in 1908 in central Athens, Panathinaikos is the oldest active football club in Greece. Its historic Apostolos Nikolaidis stadium in Ambelokipi has been the heart of Athenian sports for over a century.', history_el = 'Ιδρύθηκε το 1908 στο κέντρο της Αθήνας και αποτελεί τον παλαιότερο ενεργό ποδοσφαιρικό σύλλογο στην Ελλάδα. Το ιστορικό γήπεδο ''Απόστολος Νικολαΐδης'' στους Αμπελοκήπους αποτελεί την καρδιά του Αθηναϊκού αθλητισμού.' WHERE id = 'panathinaikos';
UPDATE team SET history_en = 'Formed in 1925 in the bustling port city of Piraeus, Olympiacos originally represented the working class and seafaring community. They are historically the most successful club in Greek football.', history_el = 'Ιδρύθηκε το 1925 στο πολυσύχναστο λιμάνι του Πειραιά, εκπροσωπώντας ιστορικά την εργατική τάξη. Είναι ο μακράν πιο επιτυχημένος σύλλογος στην ιστορία του ελληνικού ποδοσφαίρου.' WHERE id = 'olympiacos';
UPDATE team SET history_en = 'Originating in 1926 from Greek refugees from Constantinople settling in Thessaloniki, PAOK is the athletic pride of Northern Greece. Their Toumba Stadium is famous for its passionate, intense atmosphere.', history_el = 'Προερχόμενος από Έλληνες πρόσφυγες της Κωνσταντινούπολης που εγκαταστάθηκαν στη Θεσσαλονίκη το 1926, ο ΠΑΟΚ αποτελεί το αθλητικό καμάρι της Βόρειας Ελλάδας. Το ιστορικό γήπεδο της Τούμπας φημίζεται για την καυτή του ατμόσφαιρα.' WHERE id = 'paok';
UPDATE team SET history_en = 'Aris was founded in 1914 in Thessaloniki, named after Ares, the ancient Greek God of War. Historically representing the urban youth and progressive elements of Macedonia, it is one of Greece''s oldest football pillars.', history_el = 'Ο Άρης ιδρύθηκε το 1914 στη Θεσσαλονίκη, παίρνοντας το όνομά του από τον αρχαίο Θεό του Πολέμου. Εκπροσωπώντας ιστορικά τα προοδευτικά αστικά στρώματα της πόλης, είναι από τους ιστορικότερους συλλόγους της χώρας.' WHERE id = 'aris';
UPDATE team SET history_en = 'Located in Agrinio, Aetolia-Acarnania, Panetolikos was established in 1930 with a strong educational and social philosophy. It is considered the most prominent club of Western Greece.', history_el = 'Με έδρα το Αγρίνιο της Αιτωλοακαρνανίας, ο Παναιτωλικός ιδρύθηκε το 1930 με έντονο εκπαιδευτικό και κοινωνικό χαρακτήρα. Θεωρείται ο πιο εξέχων σύλλογος της Δυτικής Ελλάδας.' WHERE id = 'panetolikos';
UPDATE team SET history_en = 'Founded in 1931 in Tripoli, Arcadia, Asteras represents the central Peloponnese region. In the 21st century, the club surged from regional leagues to become a consistent European contender.', history_el = 'Ιδρύθηκε το 1931 στην Τρίπολη της Αρκαδίας και εκπροσωπεί φλογερά την κεντρική Πελοπόννησο. Τον 21ο αιώνα, η ομάδα κατάφερε από τα τοπικά πρωταθλήματα να εδραιωθεί και να αγωνιστεί στα ευρωπαϊκά κύπελλα.' WHERE id = 'asteras_tripolis';
UPDATE team SET history_en = 'Atromitos was established in 1923 and is based in Peristeri, the largest municipality in western Athens. It carries a strong, working-class, local suburban identity.', history_el = 'Ο Ατρόμητος ιδρύθηκε το 1923, με έδρα το Περιστέρι, τον μεγαλύτερο δήμο της δυτικής Αθήνας. Διαθέτει μια πολύ ισχυρή, λαϊκή ταυτότητα με απόλυτα προσηλωμένο τοπικό κοινό.' WHERE id = 'atromitos';
UPDATE team SET history_en = 'A modern club founded in 2017 in the coastal city of Volos, Thessaly. Volos NPS rapidly ascended to the Super League, representing the major port city of Central Greece in top-flight football.', history_el = 'Ένας σύγχρονος σύλλογος που ιδρύθηκε το 2017 στην παραθαλάσσια πόλη του Βόλου, στη Θεσσαλία. Ανήλθε τάχιστα στη Super League, εκπροσωπώντας επάξια το μεγάλο λιμάνι της κεντρικής Ελλάδας.' WHERE id = 'volos';
UPDATE team SET history_en = 'OFI Crete was founded in 1925 in Heraklion. It stands as the historic flagship club of the island of Crete, characterized by a fierce, proud, and fiercely loyal local fan base.', history_el = 'Ο ΟΦΗ ιδρύθηκε το 1925 στο Ηράκλειο. Αποτελεί την ιστορική ''ναυαρχίδα'' του ποδοσφαίρου στο νησί της Κρήτης, και χαρακτηρίζεται από τους εξαιρετικά περήφανους και πιστούς οπαδούς του.' WHERE id = 'ofi';
UPDATE team SET history_en = 'Founded in 1964 from a merger of local Serres teams, Panserraikos represents the Serres region in Central Macedonia. The club is known as the ''Lions'', a nod to the Lion of Amphipolis.', history_el = 'Ιδρύθηκε το 1964 ύστερα από συγχώνευση τοπικών ομάδων των Σερρών και εκπροσωπεί την περιοχή στην Κεντρική Μακεδονία. Η ομάδα είναι γνωστή ως τα ''Λιοντάρια'', εμπνευσμένο από τον Λέοντα της Αμφίπολης.' WHERE id = 'panserraikos';
UPDATE team SET history_en = 'Athlitiki Enosi Larisas (AEL) was formed in 1964 in the agricultural heartland of Thessaly. They are the only team outside of the ''Big Two'' cities (Athens/Thessaloniki) to have won the Greek Championship (1988).', history_el = 'Η Αθλητική Ένωση Λάρισας (ΑΕΛ) σχηματίστηκε το 1964. Είναι η μοναδική επαρχιακή ομάδα εκτός του δίπολου Αθήνας/Θεσσαλονίκης που κατάφερε να κατακτήσει το Πρωτάθλημα Ελλάδας (1988).' WHERE id = 'ael';
UPDATE team SET history_en = 'Based in Levadia, Central Greece, Levadiakos was formed in 1961. The club is a sporting anchor for the Boeotia region, frequently bouncing between the first and second national tiers.', history_el = 'Με έδρα τη Λιβαδειά στη Στερεά Ελλάδα, ο Λεβαδειακός ιδρύθηκε το 1961. Αποτελεί σταθερό αθλητικό σημείο αναφοράς για την περιοχή της Βοιωτίας τα τελευταία χρόνια.' WHERE id = 'levadiakos';
UPDATE team SET history_en = 'Founded in 2012 in the affluent northern suburbs of Athens, Kifisia FC is a rapidly rising modern club that recently achieved their first-ever historic promotion to the Greek Super League.', history_el = 'Ιδρύθηκε μόλις το 2012 στα βόρεια προάστια της Αθήνας. Η Κηφισιά είναι ένας σύλλογος που αναρριχήθηκε ταχύτατα, πετυχαίνοντας πρόσφατα την παρθενική του άνοδο στα μεγάλα σαλόνια της πρώτης κατηγορίας.' WHERE id = 'kifisia';
UPDATE team SET history_en = 'One of the most historic clubs in Eastern Macedonia, Kavala FC was founded in 1965.', history_el = 'Μια από τις ιστορικότερες ομάδες της Ανατολικής Μακεδονίας, η Καβάλα ιδρύθηκε το 1965.' WHERE id = 'kavala';
UPDATE team SET history_en = 'One of the oldest and most historic athletic clubs in Greece, founded in 1908 in Thessaloniki.', history_el = 'Ένας από τους παλαιότερους και ιστορικότερους αθλητικούς συλλόγους της Ελλάδας, με έδρα τη Θεσσαλονίκη (1908).' WHERE id = 'iraklis';
UPDATE team SET history_en = 'A historic pillar of Greek football established in 1890, representing the roots of Smyrna and Nea Smyrni.', history_el = 'Ιστορικός πυλώνας του ελληνικού ποδοσφαίρου με ρίζες στη Σμύρνη (1890).' WHERE id = 'panionios';
UPDATE team SET history_en = 'The prides of Epirus, known as the ''Ajax of Epirus''. Founded in 1966.', history_el = 'Το καμάρι της Ηπείρου, γνωστός και ως ''Άγιαξ της Ηπείρου''.' WHERE id = 'pas_giannina';
UPDATE team SET history_en = 'Known as the ''Black Storm'', Kalamata represents the Messenia region of the Peloponnese.', history_el = 'Γνωστή ως ''Μαύρη Θύελλα'', η Καλαμάτα εκπροσωπεί δυναμικά τη Μεσσηνία.' WHERE id = 'kalamata';
UPDATE team SET history_en = 'A historic refugee club formed in 1924, representing the working-class roots of Volos.', history_el = 'Ιστορικό προσφυγικό σωματείο που ιδρύθηκε το 1924, βασισμένο στη Νέα Ιωνία Βόλου.' WHERE id = 'niki_volou';
UPDATE team SET history_en = 'A rising force representing the majestic city of Chania, Crete.', history_el = 'Μια ανερχόμενη δύναμη που εκπροσωπεί την υπέροχη πόλη των Χανίων στην Κρήτη.' WHERE id = 'chania';
UPDATE team SET history_en = 'The ''City'' club from the western suburbs of Athens, with a rich first division history.', history_el = 'Το ''Σίτι'', αποτελεί την ιστορική φωνή των δυτικών προαστίων της Αθήνας.' WHERE id = 'egaleo';
UPDATE team SET history_en = 'The historic athletic emblem of the Karditsa region in Thessaly.', history_el = 'Το ιστορικό αθλητικό έμβλημα του νομού Καρδίτσας στη Θεσσαλία.' WHERE id = 'anagennisi_karditsas';
UPDATE team SET history_en = 'A historic multi-sport club based in Neapoli, Thessaloniki.', history_el = 'Ιστορικός πολυαθλητικός σύλλογος με έδρα τη Νεάπολη Θεσσαλονίκης.' WHERE id = 'makedonikos';
UPDATE team SET history_en = 'Athens Kallithea FC is rapidly rising as a modern cosmopolitan club from southern Athens.', history_el = 'Η Athens Kallithea FC είναι ένας ταχέως ανερχόμενος, σύγχρονος σύλλογος των νοτίων προαστίων.' WHERE id = 'kallithea';
UPDATE team SET history_en = 'Representing the region of Chalastra in Central Macedonia.', history_el = 'Εκπροσωπεί περήφανα την περιοχή της Χαλάστρας στην Κεντρική Μακεδονία.' WHERE id = 'kampaniakos';
UPDATE team SET history_en = 'The central sporting entity of the Ilioupoli municipality in Athens.', history_el = 'Ο κεντρικός αθλητικός φορέας του δήμου Ηλιούπολης στην Αθήνα.' WHERE id = 'ilioupoli';
UPDATE team SET history_en = 'A historic club representing the ancient city of Argos in the Peloponnese.', history_el = 'Ιστορική ομάδα που εκπροσωπεί την αρχαία πόλη του Άργους στην Πελοπόννησο.' WHERE id = 'panargiakos';
UPDATE team SET history_en = 'One of the oldest clubs in the Cyclades, representing the island of Syros.', history_el = 'Μία εκ των παλαιότερων ομάδων στις Κυκλάδες, εκπροσωπώντας τη Σύρο.' WHERE id = 'ellas_syrou';
UPDATE team SET history_en = 'Representing Chrysoupoli, Kavala, Nestos is a traditional force in local football.', history_el = 'Εκπροσωπώντας τη Χρυσούπολη Καβάλας, ο Νέστος είναι παραδοσιακή δύναμη.' WHERE id = 'nestos';
UPDATE team SET history_en = 'Representing Markopoulo in East Attica, established in 1927.', history_el = 'Με έδρα το Μαρκόπουλο στην Ανατολική Αττική, ιδρύθηκε το 1927.' WHERE id = 'marko';
UPDATE team SET history_en = 'The reserve development team of PAOK FC, competing to forge the next generation of northern talent.', history_el = 'Η δεύτερη ομάδα του ΠΑΟΚ, που προετοιμάζει τα νέα ταλέντα της Βόρειας Ελλάδας.' WHERE id = 'paok_b';
UPDATE team SET history_en = 'The youth development squad of Olympiacos FC, grooming future red-and-white stars.', history_el = 'Η αναπτυξιακή ομάδα του Ολυμπιακού, εξελίσσοντας ερυθρόλευκα ταλέντα.' WHERE id = 'olympiacos_b';
UPDATE team SET history_en = 'The developmental B-squad for Asteras Tripolis, offering crucial experience for academy graduates.', history_el = 'Η Β'' ομάδα του Αστέρα Τρίπολης, προσφέροντας εμπειρία στα νέα παιδιά της ακαδημίας.' WHERE id = 'asteras_b';
UPDATE team SET history_en = 'GS Doxa Dramas is a historic football club based in Drama, officially founded in 1918, with black and white as its colors and the black eagle as its emblem. The club has a long-standing presence in the national leagues, was a founding member of the Eastern Macedonia FA, reached the Greek Cup final in the 1950s, and has played multiple seasons in the top division, making it one of the most iconic provincial teams in Greek football.', history_el = 'Ο ΓΣ Δόξα Δράμας είναι ιστορικό ποδοσφαιρικό σωματείο με έδρα τη Δράμα, επίσημα ιδρυμένο το 1918, με χρώματα το μαύρο και το λευκό και έμβλημα τον μαύρο αετό. Έχει μακρά παρουσία στις εθνικές κατηγορίες, υπήρξε ιδρυτικό μέλος της Ε.Π.Σ. Ανατολικής Μακεδονίας, έφτασε σε τελικό Κυπέλλου Ελλάδας τη δεκαετία του 1950 και έχει αγωνιστεί επανειλημμένα στην Α΄ Εθνική, αποτελώντας ένα από τα πιο εμβληματικά επαρχιακά σωματεία του ελληνικού ποδοσφαίρου.' WHERE id = 'gamma_50';
UPDATE team SET history_en = 'GS Panegialios is a football club based in Aigio, founded on 25 February 1927, traditionally playing in white and black and hosting its home matches at the Aigio Municipal Stadium. It is regarded as one of the historic provincial clubs in Greece, with highlights including promotion to the Greek top division in the late 1950s and a long presence in the national leagues, which earned it the nickname “the Pashas of Aigio”.', history_el = 'Ο ΓΣ Παναιγιάλειος είναι ποδοσφαιρικός σύλλογος με έδρα το Αίγιο, ιδρυμένος στις 25 Φεβρουαρίου 1927, με χρώματα το άσπρο και το μαύρο και έδρα το Δημοτικό Στάδιο Αιγίου. Θεωρείται από τα ιστορικά σωματεία της περιφέρειας, με σημαντικές στιγμές την άνοδό του στην Α΄ Εθνική στα τέλη της δεκαετίας του 1950 και τη γενικότερη παρουσία του στις εθνικές κατηγορίες, που του χάρισαν το προσωνύμιο «οι Πασάδες του Αιγίου».' WHERE id = 'gamma_51';
UPDATE team SET history_en = 'GS Pangytheatikos is a historic sports club based in Gytheio, Laconia, founded in 1901, with blue and white as its traditional colors. It is one of the oldest clubs in the Peloponnese, best known for its football and athletics departments, having won several Laconia FA championships and cups and, in recent years, competing in the national leagues (Gamma Ethniki).', history_el = 'Ο ΓΣ Πανγυθεατικός είναι ιστορικό αθλητικό σωματείο που εδρεύει στο Γύθειο Λακωνίας, ιδρύθηκε το 1901 και έχει ως χρώματα το μπλε και το λευκό. Αποτελεί έναν από τους παλαιότερους συλλόγους της Πελοποννήσου, με κύρια τμήματα το ποδόσφαιρο και τον στίβο, και έχει κατακτήσει πολλαπλά πρωταθλήματα και κύπελλα ΕΠΣ Λακωνίας, ενώ τα τελευταία χρόνια αγωνίζεται και στις εθνικές κατηγορίες (Γ΄ Εθνική).' WHERE id = 'gamma_52';
UPDATE team SET history_en = 'Ethnikos Asteras 1927 (AO Ethnikos Asteras Kaisarianis) is a historic football club from Kaisariani, Athens, officially founded in 1927 after the merger of Ethnikos Kaisarianis and Asteras Kaisarianis, and its traditional colors are red and white. The club has a rich history in the national divisions, highlighted by a Greek Cup quarter-final run in the 1980–81 season and a memorable spell in the Greek top tier between 1998 and 2002.', history_el = 'Ο Εθνικός Αστέρας 1927 (ΑΟ Εθνικός Αστέρας Καισαριανής) είναι ιστορικό ποδοσφαιρικό σωματείο της Καισαριανής, με επίσημο έτος ίδρυσης το 1927, προερχόμενο από τη συγχώνευση του Εθνικού Καισαριανής και του Αστέρα Καισαριανής, και έχει χρώματα το κόκκινο και το λευκό. Σημαντικές στιγμές της πορείας του είναι η σταθερή παρουσία για δεκαετίες στις εθνικές κατηγορίες, η πορεία μέχρι τα προημιτελικά του Κυπέλλου Ελλάδας το 1980–81 και η ιστορική άνοδος και συμμετοχή του στην Α΄ Εθνική από το 1998 έως το 2002.' WHERE id = 'gamma_53';
UPDATE team SET history_en = 'Iraklis Thermaikou is a Greek football club based in Ampelokipoi, Thessaloniki, founded in 2019, with blue and white as its colors and the Greek letter “Η” as its crest. Since the 2025–26 season the team competes in the Gamma Ethniki, having achieved a remarkable rise through the divisions of the Macedonia Football Association within just five years.', history_el = 'Ο Ηρακλής Θερμαϊκού είναι ελληνικό ποδοσφαιρικό σωματείο που εδρεύει στους Αμπελοκήπους Θεσσαλονίκης και ιδρύθηκε το 2019, έχοντας χρώματα το μπλε και το λευκό και έμβλημα το γράμμα «Η» του ελληνικού αλφαβήτου. Από τη σεζόν 2025–26 αγωνίζεται στη Γ΄ Εθνική, μετά από μια εντυπωσιακή ανοδική πορεία μέσα σε πέντε χρόνια, με συνεχείς ανόδους από τις κατηγορίες της ΕΠΣ Μακεδονίας.' WHERE id = 'gamma_54';
UPDATE team SET history_en = 'MGS Apollon Kalamarias (Morfotikos Gymnastikos Syllogos Apollon Kalamarias) is a historic sports club from Thessaloniki, based in the suburb of Kalamaria, founded on 24 January 1926 by Pontic Greek refugees. Its colors are red and black, symbolizing the blood and mourning of the Pontic people, and its emblem is the head of the god Apollo, while the club has had a notable presence in Greek football and other sports, tightly linked to the memory and culture of the refugee community.', history_el = 'Ο ΜΓΣ Απόλλων Καλαμαριάς είναι ιστορικό αθλητικό σωματείο της Θεσσαλονίκης με έδρα την Καλαμαριά, που ιδρύθηκε στις 24 Ιανουαρίου 1926 από Πόντιους πρόσφυγες. Τα χρώματά του είναι το κόκκινο και το μαύρο, εμπνευσμένα από το αίμα και το πένθος των Ποντίων, και φέρει ως έμβλημα την κεφαλή του θεού Απόλλωνα, ενώ έχει αναδείξει σημαντική παρουσία στο ελληνικό ποδόσφαιρο και σε άλλα αθλήματα, συνδέοντας έντονα την ιστορία του με τη μνήμη και τον πολιτισμό της προσφυγιάς.' WHERE id = 'gamma_55';
UPDATE team SET history_en = 'MGS Orestis Orestiadas is a historic Greek sports club based in Orestiada, in the Evros regional unit, founded in 1927 through the merger of local clubs "Atlas" and "Ermis". Sporting light blue and white colors, the team has historically achieved notable success, including appearances in the second and third tiers of Greek football, while also winning numerous local championships and Evros Cups over its long history.', history_el = 'Ο ΜΓΣ Ορέστης Ορεστιάδας είναι ένας ιστορικός ελληνικός αθλητικός σύλλογος που εδρεύει στην Ορεστιάδα του Νομού Έβρου, έχοντας ιδρυθεί το 1927 από τη συνένωση των τοπικών σωματείων «Άτλας» και «Ερμής». Με παραδοσιακά χρώματα το γαλάζιο και το λευκό, η ομάδα έχει καταγράψει σημαντικές επιτυχίες, όπως συμμετοχές στη Β'' και Γ'' Εθνική Κατηγορία, κατακτώντας παράλληλα πολλαπλά τοπικά πρωταθλήματα και Κύπελλα Έβρου κατά τη μακρόχρονη πορεία της.' WHERE id = 'gamma_56';
UPDATE team SET history_en = 'NPS Veria 1960 represents the continuation of GAS Veria (founded in 1960 through the merger of PAO Vermion and AO Ermis) and is the city''s most historic football club, widely known by its nickname, "the ''Queen of the North". Sporting its traditional crimson and blue colors and playing at the Veria Municipal Stadium, the team officially adopted its current name (formerly NPS Veria 2019) following a court ruling in 2024, continuing its journey starting from the local divisions.', history_el = 'Ο ΝΠΣ Βέροια 1960 αποτελεί τη συνέχεια του ΓΑΣ Βέροια (που ιδρύθηκε το 1960 από συγχώνευση του ΠΑΟ Βέρμιον και του ΑΟ Ερμή) και είναι ο πιο ιστορικός ποδοσφαιρικός σύλλογος της πόλης με το προσωνύμιο «Βασίλισσα του Βορρά». Η ομάδα διατηρεί τα παραδοσιακά της χρώματα, το βυσσινί και το μπλε, αγωνίζεται στο Δημοτικό Στάδιο Βέροιας και φέρει επίσημα το νέο της όνομα (αντί για ΝΠΣ Βέροια 2019) μετά από έγκριση του Πρωτοδικείου το 2024, συνεχίζοντας την πορεία της από τις τοπικές κατηγορίες.' WHERE id = 'gamma_57';
UPDATE team SET history_en = 'OFPF Ethnikos is one of the oldest and most historic Greek football and multi-sports clubs, based in Piraeus and officially founded in 1923. The football department, sporting traditional blue and white colors, boasts 36 appearances in the Greek top tier (including 30 consecutive seasons from 1959 to 1990) and historically stands out for winning the second-ever Greek Cup during the 1932–33 season.', history_el = 'Ο ΟΦΠΦ Εθνικός είναι ένας από τους αρχαιότερους και ιστορικότερους ελληνικούς ποδοσφαιρικούς και αθλητικούς ομίλους, με έδρα τον Πειραιά και επίσημο έτος ίδρυσης το 1923. Το ποδοσφαιρικό του τμήμα, με παραδοσιακά χρώματα το μπλε και το λευκό, έχει να επιδείξει 36 παρουσίες στην Α'' Εθνική κατηγορία (εκ των οποίων οι 30 συνεχόμενες από το 1959 έως το 1990) και ξεχωρίζει ιστορικά για την κατάκτηση του δεύτερου Κυπέλλου Ελλάδας τη σεζόν 1932–33.' WHERE id = 'gamma_58';
UPDATE team SET history_en = 'PAE Akrites Sykeon is a historic football club based in Sykies, Thessaloniki, officially founded in 1939 and recognized by its blue and white colors. The club reached its peak in the 1970s when it competed in the Greek second division (1975-76), and recently, after winning the Macedonia Football Clubs Association (EPSM) championship in 2025, it secured promotion to the Gamma Ethniki following a 32-year absence from the national divisions.', history_el = 'Η ΠΑΕ Ακρίτες Συκεών είναι ένα ιστορικό ποδοσφαιρικό σωματείο της Θεσσαλονίκης με έδρα τις Συκιές, που ιδρύθηκε επίσημα το 1939 και έχει ως χρώματα το μπλε και το λευκό. Η ομάδα γνώρισε τη μεγαλύτερη ακμή της τη δεκαετία του ''70, όταν αγωνίστηκε στη Β'' Εθνική (1975-76), και πρόσφατα, μετά την κατάκτηση του πρωταθλήματος της ΕΠΣ Μακεδονίας το 2025, κέρδισε την άνοδο στη Γ'' Εθνική έπειτα από 32 χρόνια απουσίας από τις εθνικές κατηγορίες.' WHERE id = 'gamma_59';
UPDATE team SET history_en = 'PAO Doxa Vyronos is a historic Greek football club based in Vyronas, Athens, officially founded in 1945. Sporting blue and white colors, the team has a history of competing in the second and third tiers of Greek football and recently celebrated its promotion back to the Gamma Ethniki in 2025, following an 11-year absence.', history_el = 'Ο ΠΑΟ Δόξα Βύρωνος είναι ένας ιστορικός ελληνικός ποδοσφαιρικός σύλλογος που εδρεύει στον Βύρωνα Αττικής και ιδρύθηκε επίσημα το 1945. Έχοντας ως χρώματα το μπλε και το λευκό, η ομάδα έχει καταγράψει πολλές συμμετοχές στη Β'' και Γ'' Εθνική κατηγορία στο παρελθόν, ενώ το 2025 πανηγύρισε την επιστροφή της στη Γ'' Εθνική έπειτα από 11 χρόνια απουσίας.' WHERE id = 'gamma_60';
UPDATE team SET history_en = 'PAO Kentavros Vrilission is an amateur football club based in Vrilissia, Athens, established in 2003 by a group of 29 people aiming to create a model academy and a healthy sporting environment for local youth. The club achieved its most historic milestone during the 2024–25 season by winning the Group 1 championship of the Athens Football Clubs Association (EPSA) First Division for the first time, thereby securing promotion to the Gamma Ethniki (the Greek third tier).', history_el = 'Ο ΠΑΟ Κένταυρος Βριλησσίων είναι ερασιτεχνικό ποδοσφαιρικό σωματείο της Αθήνας, με έδρα τα Βριλήσσια, το οποίο ιδρύθηκε το 2003 αρχικά ως παρέα 29 ατόμων με στόχο τη δημιουργία μιας πρότυπης ακαδημίας και ενός υγιούς αθλητικού περιβάλλοντος για τους νέους. Τη σεζόν 2024–25 σημείωσε την πιο ιστορική του επιτυχία, κατακτώντας για πρώτη φορά το πρωτάθλημα του 1ου ομίλου της Α΄ Κατηγορίας της ΕΠΣ Αθηνών και εξασφαλίζοντας την άνοδο στη Γ΄ Εθνική κατηγορία.' WHERE id = 'gamma_61';
UPDATE team SET history_en = 'PAOK Dytikou is an amateur football club based in Dytiko, a small village in the Pella regional unit of Greece. The team achieved a historic milestone for its local community by winning the Pella Football Clubs Association (EPS Pella) championship, which earned them promotion to the Gamma Ethniki (the Greek third tier) for the first time in their history.', history_el = 'Ο ΠΑΟΚ Δυτικού είναι ένας ερασιτεχνικός ποδοσφαιρικός σύλλογος που εδρεύει στο Δυτικό Πέλλας, ένα μικρό χωριό του δήμου Πέλλας. Η ομάδα κατέγραψε μια ιστορική επιτυχία για την περιοχή της κατακτώντας το πρωτάθλημα της ΕΠΣ Πέλλας, γεγονός που της εξασφάλισε για πρώτη φορά στην ιστορία της την άνοδο στη Γ'' Εθνική Κατηγορία.' WHERE id = 'gamma_62';
UPDATE team SET history_en = 'PAOK Kristonis is an amateur football club based in Kristoni, in the Kilkis regional unit, competing in the Greek national divisions and recognized as one of the most competitive teams in its region. The team has won multiple championships in the Kilkis Football Clubs Association (EPS Kilkis), competed in both the Delta and Gamma Ethniki tiers, and notably reached the third round of the Greek Cup in 2022.', history_el = 'Ο ΠΑΟΚ Κρηστώνης είναι ένας ερασιτεχνικός ποδοσφαιρικός σύλλογος που εδρεύει στην Κρηστώνη του νομού Κιλκίς και αγωνίζεται στις εθνικές κατηγορίες, αποτελώντας μία από τις πιο ανταγωνιστικές ομάδες της περιοχής του. Η ομάδα έχει κατακτήσει πολλαπλά πρωταθλήματα στην ΕΠΣ Κιλκίς, έχει αγωνιστεί στη Δ'' και Γ'' Εθνική κατηγορία, και το 2022 ξεχώρισε με τη συμμετοχή της μέχρι τον τρίτο γύρο του Κυπέλλου Ελλάδας.' WHERE id = 'gamma_63';
UPDATE team SET history_en = 'PAS Korinthos is a historic Greek football club based in the city of Korinthos. Originally founded in 1963 as APS Korinthos (through the merger of Pankorinthiakos and Aris Korinthou), it adopted its current name in 1999 following a new merger. Sporting red, yellow, and black colors, the team plays its home matches at the Corinth Municipal Stadium and has historically spent several seasons competing in the Greek top tier.', history_el = 'Ο ΠΑΣ Κόρινθος είναι ένα ιστορικό ελληνικό ποδοσφαιρικό σωματείο που εδρεύει στην Κόρινθο. Ιδρύθηκε αρχικά το 1963 ως ΑΠΣ Κόρινθος (από τη συγχώνευση του Παγκορινθιακού με τον Άρη Κορίνθου) και πήρε τη σημερινή του ονομασία το 1999 έπειτα από νέα συγχώνευση. Έχει ως χρώματα το κόκκινο, το κίτρινο και το μαύρο, αγωνίζεται στο Δημοτικό Στάδιο Κορίνθου και στο παρελθόν έχει συμμετάσχει αρκετές σεζόν στην Α'' Εθνική κατηγορία.' WHERE id = 'gamma_64';
UPDATE team SET history_en = 'PAS Lamia 1964 is a Greek professional football club based in Lamia, officially founded on June 1, 1964, following the merger of local clubs Pamfthiotikos, Olympiakos Lamias, and Pallamiaki. Sporting blue and white colors and playing its home matches at the Lamia Municipal Sports Center, the team has established itself as a steady presence in the professional tiers of Greek football in recent years.', history_el = 'Ο ΠΑΣ Λαμία 1964 είναι ελληνικός επαγγελματικός ποδοσφαιρικός σύλλογος της Λαμίας που ιδρύθηκε επίσημα την 1η Ιουνίου 1964, ύστερα από τη συγχώνευση των τοπικών συλλόγων Παμφθιωτικού, Ολυμπιακού Λαμίας (ως Λαμιακός) και Παλλαμιακής. Η ομάδα εδρεύει στο Δημοτικό Αθλητικό Κέντρο Λαμίας, χρησιμοποιεί ως χρώματα το μπλε και το λευκό, και έχει καθιερωθεί τα τελευταία χρόνια στις επαγγελματικές κατηγορίες του ελληνικού ποδοσφαίρου.' WHERE id = 'gamma_65';
UPDATE team SET history_en = 'PAS Pyrgos 1968 is a Greek football club based in Pyrgos (Ilia), formed in 2025 when AO Thyella Katarrachiou Pyrgou (originally founded in 1968) absorbed the historic club Paniliakos. Sporting the red and white colors and the torch emblem of Paniliakos, the team plays its home matches at the Municipal Stadium of Pyrgos and competes in the Gamma Ethniki, while also maintaining a women''s football team.', history_el = 'Ο ΠΑΣ Πύργος 1968 είναι ένα ελληνικό ποδοσφαιρικό σωματείο που εδρεύει στον Πύργο Ηλείας και προέκυψε το 2025 μετά την απορρόφηση του ιστορικού Πανηλειακού από την ομάδα ΑΟ Θύελλα Καταρραχίου Πύργου (η οποία είχε ιδρυθεί το 1968). Η ομάδα διατηρεί το έμβλημα του πυρσού του Πανηλειακού, χρησιμοποιεί τα ερυθρόλευκα χρώματα και αγωνίζεται στο Δημοτικό Στάδιο Πύργου, έχοντας παρουσία στο πρωτάθλημα της Γ'' Εθνικής καθώς και γυναικείο τμήμα.' WHERE id = 'gamma_66';
UPDATE team SET history_en = 'PO Atsaleniou (POA) is a historic Greek sports club based in Atsalenio, a suburb of Heraklion, Crete, founded in 1951 by Asia Minor refugees. Considered one of the most dynamic clubs in Heraklion, the team plays its home matches at the privately owned Atsalenios Stadium, established in 1960, and has predominantly competed in the Gamma Ethniki and Delta Ethniki divisions.', history_el = 'Ο ΠO Ατσαλένιου (ΠΟΑ) είναι ένας ιστορικός ελληνικός αθλητικός σύλλογος που εδρεύει στο Ατσαλένιο, ένα προάστιο του Ηρακλείου Κρήτης, και ιδρύθηκε το 1951 από Μικρασιάτες πρόσφυγες. Η ομάδα θεωρείται από τις πιο δυναμικές του Ηρακλείου, χρησιμοποιεί ως έδρα το ιδιόκτητο Γήπεδο Ατσαλένιου από το 1960 και έχει αγωνιστεί κυρίως στη Γ'' και Δ'' Εθνική κατηγορία.' WHERE id = 'gamma_67';
UPDATE team SET history_en = 'PO Elassonas is a historic football club from Elassona in the Larisa region, originally founded in 1922 as Proodeftikos Omilos before being re-established under its current name in 1957. Playing its home matches at the Elassona Municipal Stadium, the team has historically competed as high as the Greek second tier and, after a brief merger with local rival AO Olosson in 2007, reverted to its traditional name and identity in 2011.', history_el = 'Ο ΠO Ελασσόνας είναι ένας ιστορικός σύλλογος από την Ελασσόνα του Νομού Λάρισας, που ιδρύθηκε αρχικά το 1922 ως Προοδευτικός Όμιλος και επανιδρύθηκε το 1957 με τη σημερινή του ονομασία. Η ομάδα, που αγωνίζεται στο Δημοτικό Στάδιο Ελασσόνας και έχει συμμετάσχει μέχρι και στη Β'' Εθνική κατηγορία, το 2007 συγχωνεύτηκε με τον ΑΟ Ολοσσών πριν επιστρέψει στο παραδοσιακό όνομα και σήμα της το 2011.' WHERE id = 'gamma_68';
UPDATE team SET history_en = 'Proodos Rogon 1966 is an amateur football club based in Nea Kerasounta (Arta) and playing its home matches at the Nea Kerasounta ground. Despite the “1966” in its name, it got founded just at 2023', history_el = 'Η Πρόοδος Ρωγών 1966 είναι ερασιτεχνικό ποδοσφαιρικό σωματείο που εδρεύει στη Νέα Κερασούντα (Άρτα) και χρησιμοποιεί ως έδρα το γήπεδο Νέας Κερασούντας. Παρότι η ονομασία περιλαμβάνει το «1966», ιδρύθηκε μόλις το 2023.' WHERE id = 'gamma_69';
UPDATE team SET history_en = 'PS Ethnikos Neo Keramidi is a Greek professional football club founded in 1951 and based in the small village of Neo Keramidi, near Katerini in the Pieria region. The team achieved the greatest milestone in its history during the 2023-2024 season by winning their Gamma Ethniki group and earning promotion to the professional Super League 2 for the very first time.', history_el = 'Ο ΠΣ Εθνικός Νέου Κεραμιδίου είναι ένας ελληνικός ποδοσφαιρικός σύλλογος που ιδρύθηκε το 1951 και εδρεύει στο Νέο Κεραμίδι Πιερίας, ένα μικρό χωριό δίπλα στην Κατερίνη. Η ομάδα πέτυχε τη σημαντικότερη διάκριση στην ιστορία της τη σεζόν 2023-2024, κατακτώντας το πρωτάθλημα στον όμιλό της στη Γ'' Εθνική και εξασφαλίζοντας για πρώτη φορά την άνοδο στις επαγγελματικές κατηγορίες και τη Super League 2.' WHERE id = 'gamma_70';
UPDATE team SET history_en = 'SFK Pierikos is a historic Greek football club based in Katerini, founded on April 11, 1961, following the merger of local clubs Megas Alexandros and Olympos Katerinis. It is the most successful club in the Pieria regional unit, having spent many seasons in the Greek top tier and reaching the Greek Cup final in 1963, where they played against Olympiacos.', history_el = 'Ο ΣΦΚ Πιερικός είναι ένας ιστορικός ελληνικός ποδοσφαιρικός σύλλογος της Κατερίνης, που ιδρύθηκε στις 11 Απριλίου 1961 έπειτα από τη συγχώνευση των τοπικών ομάδων Μέγα Αλέξανδρου και Ολύμπου Κατερίνης. Αποτελεί την πλέον επιτυχημένη ομάδα του Νομού Πιερίας, έχοντας αγωνιστεί αρκετές χρονιές στην Α'' Εθνική με κορυφαία διάκριση τη συμμετοχή του στον τελικό του Κυπέλλου Ελλάδος το 1963 απέναντι στον Ολυμπιακό.' WHERE id = 'gamma_71';
UPDATE team SET history_en = 'FS Eordaikos Ptolemaida is a historic football club from Western Macedonia, Greece, founded in 1978 through the merger of local teams Aris and Ptolemaios. Based in the city of Ptolemaida, the team sports green and yellow colors and has historically competed in the second and third tiers of Greek football.', history_el = 'Ο ΦΣ Εορδαϊκός Πτολεμαΐδας είναι ένας ιστορικός ποδοσφαιρικός σύλλογος της Δυτικής Μακεδονίας που ιδρύθηκε το 1978 από τη συγχώνευση των τοπικών ομάδων Άρη και Πτολεμαίου. Η ομάδα εδρεύει στην Πτολεμαΐδα, έχει χρώματα το πράσινο και το κίτρινο, και στο παρελθόν έχει αγωνιστεί αρκετές χρονιές στη Β'' και Γ'' Εθνική κατηγορία.' WHERE id = 'gamma_72';
UPDATE team SET history_en = 'FS Kozani is a Greek football club founded in 1964 following the merger of local teams Makedonikos and Olympiakos Kozanis. Based in the city of Kozani, the team plays its home matches at the Municipal Stadium of Kozani and sports red and white as its official colors.', history_el = 'Ο ΦΣ Κοζάνη είναι ένας ιστορικός ελληνικός ποδοσφαιρικός σύλλογος που ιδρύθηκε το 1964, προερχόμενος από τη συγχώνευση των τοπικών ομάδων Μακεδονικού και Ολυμπιακού Κοζάνης. Η ομάδα αγωνίζεται στο Δημοτικό Στάδιο Κοζάνης και έχει ως παραδοσιακά της χρώματα το κόκκινο και το λευκό.' WHERE id = 'gamma_73';
